def backfill_expense_dates_and_material_unit_costs(apps, schema_editor):
    """Preserve history without recomputing any finalized product cost.

    Expense dates default to the first day of their recorded month. Direct-material
    unit costs are a snapshot of the already-stored material amount assigned to
    good output divided by the already-stored good units, not a new costing run.
    """
    MonthlyExpense = apps.get_model("costing", "MonthlyExpense")
    ProductCostingEntry = apps.get_model("costing", "ProductCostingEntry")

    for expense in MonthlyExpense.objects.filter(expense_date__isnull=True).iterator():
        MonthlyExpense.objects.filter(pk=expense.pk).update(
            expense_date=date(expense.year, expense.month, 1)
        )

    for entry in ProductCostingEntry.objects.filter(
        material_cost_per_good_unit__isnull=True,
        good_units_produced__gt=0,
    ).iterator():
        value = (
            entry.material_cost_assigned_to_good / entry.good_units_produced
        ).quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP)
        ProductCostingEntry.objects.filter(pk=entry.pk).update(
            material_cost_per_good_unit=value
        )


